#include "postquantiquecoin/core/Logger.h"
#include <chrono>
#include <fstream>
#include <iostream>
namespace pqc { namespace { LogLevel level=LogLevel::Info; std::filesystem::path file; bool Sensitive(const std::string& m){ auto l=m; for(auto& c:l)c=static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return l.find("private key")!=std::string::npos||l.find("master key")!=std::string::npos||l.find("password")!=std::string::npos||l.find("shared secret")!=std::string::npos||l.find("dek")!=std::string::npos; } void Log(LogLevel l,const char* n,const std::string& cat,const std::string& msg){ if(static_cast<int>(l)<static_cast<int>(level)) return; std::string safe=Sensitive(msg)?"[redacted sensitive wallet/crypto material]":msg; std::string line="["+std::string(n)+"]["+cat+"] "+safe+"\n"; if(!file.empty()){ std::ofstream out(file,std::ios::app); out<<line; } else std::cerr<<line; } } void Logger::SetLogLevel(LogLevel l){level=l;} void Logger::SetLogFile(const std::filesystem::path& p){file=p;} void Logger::RotateLogs(){ if(!file.empty()&&std::filesystem::exists(file)) std::filesystem::rename(file,file.string()+".1"); } void Logger::LogInfo(const std::string& c,const std::string& m){Log(LogLevel::Info,"info",c,m);} void Logger::LogWarn(const std::string& c,const std::string& m){Log(LogLevel::Warn,"warn",c,m);} void Logger::LogError(const std::string& c,const std::string& m){Log(LogLevel::Error,"error",c,m);} void Logger::LogDebug(const std::string& c,const std::string& m){Log(LogLevel::Debug,"debug",c,m);} }
